using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private PriceCalculator _calculator = null!;

    [TestInitialize]
    public void Setup() => _calculator = new PriceCalculator();

    // ───────────────────────────────────────────────
    //  CalculateTotal – DataRow (compile-time constants)
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(0,   1,  0.0,  0.0,   DisplayName = "Zero price yields zero total")]
    [DataRow(10,  0,  0.1,  0.0,   DisplayName = "Zero quantity yields zero total")]
    [DataRow(10,  1,  0.0,  10.0,  DisplayName = "No tax – total equals subtotal")]
    [DataRow(10,  2,  0.1,  22.0,  DisplayName = "Basic tax calculation")]
    [DataRow(5.5, 3,  0.2,  19.8,  DisplayName = "Fractional price with tax")]
    [DataRow(100, 1,  1.0,  200.0, DisplayName = "100% tax doubles the price")]
    public void CalculateTotal_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal(
            (decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    //  CalculateTotal – DynamicData (decimal precision)
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> CalculateTotalCases
    {
        get
        {
            yield return [19.99m, 3,  0.08m,  64.7676m,  "Realistic retail scenario"];
            yield return [0.01m,  1,  0.05m,  0.0105m,   "Smallest meaningful price"];
            yield return [999.99m, 10, 0.23m, 12299.877m, "High-value order with VAT"];
        }
    }

    [TestMethod]
    [DynamicData(nameof(CalculateTotalCases))]
    public void CalculateTotal_DynamicData_ReturnsExpected(
        decimal unitPrice, int quantity, decimal taxRate,
        decimal expected, string scenario)
    {
        var result = _calculator.CalculateTotal(unitPrice, quantity, taxRate);

        Assert.AreEqual(expected, result, $"Failed for: {scenario}");
    }

    // ───────────────────────────────────────────────
    //  CalculateTotal – invalid inputs
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(-1,  1, 0.1, DisplayName = "Negative unit price throws")]
    [DataRow(10, -1, 0.1, DisplayName = "Negative quantity throws")]
    [DataRow(10,  1, -0.1, DisplayName = "Negative tax rate throws")]
    [DataRow(10,  1, 1.5,  DisplayName = "Tax rate > 1 throws")]
    public void CalculateTotal_InvalidInput_Throws(
        double unitPrice, int quantity, double taxRate)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(
                (decimal)unitPrice, quantity, (decimal)taxRate));
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – DataRow
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.0,  0.0,  100.0, DisplayName = "0% discount – unchanged")]
    [DataRow(100.0, 50.0,   50.0, DisplayName = "50% discount – halved")]
    [DataRow(100.0, 100.0,   0.0, DisplayName = "100% discount – free")]
    [DataRow(49.99, 10.0,  44.991, DisplayName = "Fractional result")]
    [DataRow(0.0,   25.0,   0.0,  DisplayName = "Zero price stays zero")]
    public void ApplyDiscount_ReturnsExpected(
        double price, double discountPercent, double expected)
    {
        var result = _calculator.ApplyDiscount(
            (decimal)price, (decimal)discountPercent);

        Assert.AreEqual((decimal)expected, result);
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – DynamicData via method
    // ───────────────────────────────────────────────

    public static IEnumerable<object[]> DiscountEdgeCases()
    {
        yield return [200.00m, 33.33m, 133.34m, "Repeating-decimal discount"];
        yield return [1000m,   15m,    850m,    "Typical coupon"];
        yield return [0.50m,   99m,    0.005m,  "Near-total discount on small price"];
    }

    [TestMethod]
    [DynamicData(nameof(DiscountEdgeCases), DynamicDataSourceType.Method)]
    public void ApplyDiscount_DynamicData_ReturnsExpected(
        decimal price, decimal discountPercent,
        decimal expected, string scenario)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result, $"Failed for: {scenario}");
    }

    // ───────────────────────────────────────────────
    //  ApplyDiscount – invalid inputs
    // ───────────────────────────────────────────────

    [TestMethod]
    [DataRow(100.0, -1.0,  DisplayName = "Negative discount throws")]
    [DataRow(100.0, 101.0, DisplayName = "Discount > 100 throws")]
    public void ApplyDiscount_InvalidDiscount_Throws(
        double price, double discountPercent)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(
                (decimal)price, (decimal)discountPercent));
    }
}

